  /* Hover and press mix from --button-bg and --button-fg, so overrides get
     matching shades. Filled or not, every button sits on the one control
     shadow: no glint along the top, nothing darker under the bottom edge. */
  .button[data-variant="primary"] {
    --button-depth: var(--ui-shadow-control);
    --button-bg: var(--ui-ink);
    --button-bg-hover: color-mix(in oklch, var(--button-bg) 92%, var(--button-fg));
    --button-bg-press: color-mix(in oklch, var(--button-bg) 85%, var(--button-fg));
    --button-fg: var(--ui-on-ink);
  }

  .button[data-variant="secondary"] {
    --button-bg: var(--ui-surface);
    --button-edge: var(--ui-border-strong);
    --button-depth: var(--ui-shadow-control);
  }

  .button[data-variant="danger"] {
    --button-depth: var(--ui-shadow-control);
    --button-bg: var(--ui-danger);
    --button-bg-hover: color-mix(in oklch, var(--button-bg) 93%, black);
    --button-bg-press: color-mix(in oklch, var(--button-bg) 86%, black);
    --button-fg: var(--ui-on-danger);
